# Whats changed
- Route function annotation support for `Body`, `Query`, `Form`, `Header` etc.
```python
# WITHOUT TYPE ANNOTATION
@post("/items/")
def save_union_body_and_embedded_body(
    item: Union[OtherItem, Item], qty: int = Body(12)
):
    return {"item": item, "qty": qty}

# WITH TYPE ANNOTATION

@post("/items/")
def save_union_body_and_embedded_body(
    item: Body[Union[OtherItem, Item]], qty:Body[int, Body.P(default=12)]
):
    return {"item": item, "qty": qty}

# INJECTING OTHER DEPENDENCIES

@get("/others")
def get_requests_case_2(
    session: Inject[dict, Inject.Key("Session")], # injects session value from request object
    host: Inject[str, Inject.Key("Host")], # injects host value from request object
    config: Inject[Config], # injects application Config object from DI
):
    assert isinstance(config, Config)  # True
    assert host == "testclient"
    assert isinstance(session, dict) and len(session) == 0
    return True
```

