### Changes made:
- Retreive required roles:
    ```javascript
            useEffect(() => {
                const roles =
                  requiredSignoffs.data &&
                  requiredSignoffs.data.data.required_signoffs.map(el => {
                    return el.role;
                  });

                setRequiredRoles(roles);
            }, []);
    ```
- Disable roles that are not required
    ```javascript
        const signoffDialogBody = (
            <FormControl component="fieldset">
              <RadioGroup
                aria-label="Role"
                name="role"
                value={signoffRole}
                onChange={handleSignoffRoleChange}>
                {roles.map(r => {
                  return (
                    <FormControlLabel
                      key={r}
                      value={r}
                      label={r}
                      control={<Radio />}
                      disabled={!(requiredRoles && requiredRoles.includes(r))}
                    />
                  );
                })}
              </RadioGroup>
            </FormControl>
        );
    ```
- If the user has only one role in the required role list, `signoff` directly:
    ```javascript
          const handleSignoff = async rule => {
            const userRequiredRoles = requiredRoles.filter(r => roles.includes(r));

            if (userRequiredRoles.length === 1) {
              const { error, result } = await doSignoff(userRequiredRoles[0], rule);

              if (!error) {
                updateSignoffs(result);
              }
            } else {
              setDialogState({
                ...dialogState,
                open: true,
                title: 'Signoff as…',
                confirmText: 'Sign off',
                item: rule,
                mode: 'signoff',
                handleComplete: handleSignoffDialogComplete,
                handleSubmit: handleSignoffDialogSubmit,
              });
            }
  };
    ```

